package at.hausgarten.service;
import org.json.*;

public final class DriveJournalTests {
    interface Case {void run()throws Exception;}static int passed;
    static void check(String name,Case task)throws Exception{task.run();passed++;System.out.println("PASS "+name);}
    static void yes(boolean value){if(!value)throw new AssertionError();}
    static void rejects(Case task)throws Exception{try{task.run();}catch(IllegalArgumentException expected){return;}throw new AssertionError("Expected rejection");}
    static JSONObject snapshot()throws Exception{return new JSONObject("{\"customers\":[{\"id\":\"c1\",\"name\":\"Test Kunde\",\"updated_at\":\"2026-10-12T08:00:00Z\"}],\"orders\":[],\"worklogs\":[],\"photos\":[],\"invoices\":[],\"accepted_ids\":[]}");}
    static JSONObject work(String id)throws Exception{return new JSONObject().put("id",id).put("customer_id","c1").put("order_id","").put("work_date","2026-10-12").put("activity","Heckenschnitt").put("hours",3);}
    static JSONObject action(String id,String kind,JSONObject row)throws Exception{return new JSONObject().put("client_id",id).put("kind",kind).put("payload",row).put("created_at","2026-10-12T10:00:00Z");}
    static JSONArray one(JSONObject a){return new JSONArray().put(a);}
    public static void main(String[] args)throws Exception{
        check("complete snapshot valid",()->DriveJournalRules.validateSnapshot(snapshot()));
        check("missing collection fails closed",()->rejects(()->{JSONObject s=snapshot();s.remove("photos");DriveJournalRules.validateSnapshot(s);}));
        check("duplicate primary key rejected",()->rejects(()->{JSONObject s=snapshot();s.getJSONArray("customers").put(s.getJSONArray("customers").getJSONObject(0));DriveJournalRules.validateSnapshot(s);}));
        check("empty primary key rejected",()->rejects(()->{JSONObject s=snapshot();s.getJSONArray("customers").put(new JSONObject().put("id",""));DriveJournalRules.validateSnapshot(s);}));
        JSONObject a=action("action-1","worklog",work("w1"));
        check("same request id merges once",()->yes(DriveJournalRules.union(one(a),one(a)).length()==1));
        check("distinct pending and remote ids retained",()->yes(DriveJournalRules.union(one(a),one(action("action-2","worklog",work("w2")))).length()==2));
        check("same id different payload fails closed",()->rejects(()->DriveJournalRules.union(one(a),one(action("action-1","worklog",work("w2"))))));
        check("invalid envelope rejected",()->rejects(()->DriveJournalRules.union(one(new JSONObject().put("kind","worklog")))));
        check("merge never mutates source",()->{JSONArray x=DriveJournalRules.union(one(a));x.getJSONObject(0).getJSONObject("payload").put("hours",9);yes(a.getJSONObject("payload").getInt("hours")==3);});
        check("work without order applies with unchanged ids",()->{JSONObject s=snapshot();yes(DriveJournalRules.apply(s,one(a)).length()==0);yes(s.getJSONArray("worklogs").getJSONObject(0).getString("id").equals("w1"));});
        check("defaults applied only to new work",()->{JSONObject s=snapshot();DriveJournalRules.apply(s,one(a));JSONObject r=s.getJSONArray("worklogs").getJSONObject(0);yes(r.getInt("break_minutes")==0&&r.getInt("customer_visible")==1&&r.getInt("billed")==0&&r.getDouble("kilometers")==0);});
        check("repeated journal does not duplicate",()->{JSONObject s=snapshot();DriveJournalRules.apply(s,one(a));DriveJournalRules.apply(s,one(a));yes(s.getJSONArray("worklogs").length()==1);});
        check("already laptop accepted not reapplied",()->{JSONObject s=snapshot();s.getJSONArray("accepted_ids").put("action-1");DriveJournalRules.apply(s,one(a));yes(s.getJSONArray("worklogs").length()==0);});
        check("tampered accepted journal id detected",()->{JSONObject s=snapshot();DriveJournalRules.apply(s,one(a));rejects(()->DriveJournalRules.apply(s,one(action("action-1","worklog",work("w2")))));});
        check("unknown customer leaves existing snapshot intact",()->{JSONObject s=snapshot();String before=s.getJSONArray("worklogs").toString();JSONArray errors=DriveJournalRules.apply(s,one(action("bad","worklog",work("w1").put("customer_id","missing"))));yes(errors.length()==1&&s.getJSONArray("worklogs").toString().equals(before));});
        check("foreign order customer mismatch rejected",()->{JSONObject s=snapshot();s.getJSONArray("orders").put(new JSONObject().put("id","o1").put("customer_id","c2"));yes(DriveJournalRules.apply(s,one(action("bad","worklog",work("w1").put("order_id","o1")))).length()==1);});
        check("negative hours rejected",()->yes(DriveJournalRules.apply(snapshot(),one(action("bad","worklog",work("w1").put("hours",-1)))).length()==1));
        check("invalid date rejected",()->yes(DriveJournalRules.apply(snapshot(),one(action("bad","worklog",work("w1").put("work_date","2026-02-30")))).length()==1));
        check("hours calculation independently verified",()->{JSONObject s=snapshot();JSONObject row=work("w1").put("start_time","08:00").put("end_time","14:30").put("break_minutes",60).put("hours",5.5);yes(DriveJournalRules.apply(s,one(action("time","worklog",row))).length()==0);yes(s.getJSONArray("worklogs").getJSONObject(0).getDouble("hours")==5.5);});
        check("clock/hour disagreement not silently repaired",()->yes(DriveJournalRules.apply(snapshot(),one(action("time","worklog",work("w1").put("start_time","08:00").put("end_time","12:00")))).length()==1));
        check("empty work date does not default during import",()->yes(DriveJournalRules.apply(snapshot(),one(action("bad","worklog",work("w1").put("work_date","")))).length()==1));
        check("guarded update succeeds",()->{JSONObject s=snapshot();DriveJournalRules.apply(s,one(a));JSONObject old=s.getJSONArray("worklogs").getJSONObject(0);JSONObject update=new JSONObject(old.toString()).put("notes","Ergänzung").put("_sync_base",DriveJournalRules.guard(old,"worklog"));yes(DriveJournalRules.apply(s,one(action("edit","worklog",update))).length()==0);yes(s.getJSONArray("worklogs").getJSONObject(0).getString("notes").equals("Ergänzung"));});
        check("parallel web edit causes conflict not overwrite",()->{JSONObject s=snapshot();DriveJournalRules.apply(s,one(a));JSONObject old=s.getJSONArray("worklogs").getJSONObject(0);JSONObject update=new JSONObject(old.toString()).put("hours",4).put("_sync_base",DriveJournalRules.guard(old,"worklog"));old.put("notes","Web Änderung");JSONArray errors=DriveJournalRules.apply(s,one(action("edit","worklog",update)));yes(errors.getJSONObject(0).getString("code").equals("WRITE_CONFLICT"));yes(old.getString("notes").equals("Web Änderung"));});
        check("unguarded historical edit needs review",()->{JSONObject s=snapshot();DriveJournalRules.apply(s,one(a));yes(DriveJournalRules.apply(s,one(action("old-edit","worklog",work("w1").put("hours",4)))).length()==1);yes(s.getJSONArray("worklogs").getJSONObject(0).getDouble("hours")==3);});
        check("invoice/delete workflows not acknowledged by journal",()->{JSONObject s=snapshot();DriveJournalRules.apply(s,one(action("delete","delete",new JSONObject().put("entity","customer").put("id","c1"))));yes(s.getJSONArray("drive_applied_ids").length()==0&&s.getJSONArray("customers").length()==1);});
        check("valid actions survive sibling validation error",()->{JSONObject s=snapshot();JSONArray all=one(action("bad","worklog",work("bad").put("customer_id","missing"))).put(a);yes(DriveJournalRules.apply(s,all).length()==1&&s.getJSONArray("worklogs").length()==1);});
        check("new offline customer then work relation",()->{JSONObject s=snapshot();JSONArray all=one(action("new-c","customer",new JSONObject().put("id","c2").put("name","Anderer Kunde"))).put(action("new-w","worklog",work("w2").put("customer_id","c2")));yes(DriveJournalRules.apply(s,all).length()==0&&s.getJSONArray("worklogs").getJSONObject(0).getString("customer_id").equals("c2"));});
        check("new customer duplicate including inactive rejected",()->{JSONObject s=snapshot();s.getJSONArray("customers").getJSONObject(0).put("active",0);yes(DriveJournalRules.apply(s,one(action("new-c","customer",new JSONObject().put("id","c2").put("name","Test Kunde")))).length()==1);});
        check("photo relation rejected safely",()->yes(DriveJournalRules.apply(snapshot(),one(action("photo","photo",new JSONObject().put("id","p1").put("customer_id","c1").put("worklog_id","missing")))).length()==1));
        check("typed custom field comparison",()->{JSONObject old=new JSONObject().put("id","c").put("custom_fields","{\"Anzahl\":1.0}");DriveJournalRules.compare(new JSONObject().put("id","c").put("custom_fields",new JSONObject().put("Anzahl",1)),old);rejects(()->DriveJournalRules.compare(new JSONObject().put("id","c").put("custom_fields",new JSONObject().put("Anzahl",true)),old));});
        check("customer name display aliases refresh without laptop",()->{JSONObject s=snapshot();JSONObject old=s.getJSONArray("customers").getJSONObject(0);s.getJSONArray("worklogs").put(work("w1").put("customer_name","Alter Anzeigename"));JSONObject row=new JSONObject(old.toString()).put("name","Neuer Anzeigename").put("_sync_base",DriveJournalRules.guard(old,"customer"));yes(DriveJournalRules.apply(s,one(action("name-edit","customer",row))).length()==0);yes(s.getJSONArray("worklogs").getJSONObject(0).getString("customer_name").equals("Neuer Anzeigename"));yes(s.getJSONArray("worklogs").getJSONObject(0).getString("customer_id").equals("c1"));});
        check("explicit duplicate confirmation remains compatible but not persisted",()->{JSONObject s=snapshot();yes(DriveJournalRules.apply(s,one(action("confirmed-duplicate","customer",new JSONObject().put("id","c2").put("name","Test Kunde").put("allow_duplicate",true)))).length()==0);yes(s.getJSONArray("customers").length()==2&&!s.getJSONArray("customers").getJSONObject(1).has("allow_duplicate"));});
        check("delivered deletes remain retained but no longer await transfer",()->{JSONObject s=snapshot().put("drive_delivered_ids",new JSONArray().put("held"));JSONArray p=one(action("held","delete",new JSONObject().put("entity","customer").put("id","c1")));JSONObject q=DriveJournalRules.queueStatus(s,p);yes(q.getInt("pending_upload")==0&&q.getInt("review")==1&&p.length()==1&&s.getJSONArray("customers").length()==1);yes(!q.getJSONArray("items").getJSONObject(0).getBoolean("cloud_confirmed"));});
        check("conflicts are review not endless network retry",()->{JSONObject s=snapshot().put("drive_journal_errors",one(new JSONObject().put("client_id","bad").put("code","WRITE_CONFLICT")));JSONObject q=DriveJournalRules.queueStatus(s,one(action("bad","customer",new JSONObject().put("id","c1"))));yes(q.getInt("review")==1&&q.getInt("pending_upload")==0);yes(q.getJSONArray("items").getJSONObject(0).getString("state").equals("sync_conflict"));});
        check("unverified deletes cannot look delivered",()->{JSONObject q=DriveJournalRules.queueStatus(snapshot(),one(action("new","delete",new JSONObject().put("id","c1"))));yes(q.getInt("pending_upload")==1&&q.getInt("review")==0&&!q.getJSONArray("items").getJSONObject(0).getBoolean("provider_readback"));});
        check("mixed queue accurately counts network pending and protected review",()->{JSONObject s=snapshot().put("drive_delivered_ids",new JSONArray().put("held"));JSONArray p=one(action("held","delete",new JSONObject())).put(action("fresh","worklog",work("w1")));JSONObject q=DriveJournalRules.queueStatus(s,p);yes(q.getInt("total")==2&&q.getInt("review")==1&&q.getInt("pending_upload")==1&&p.length()==2);});
        check("transient UI pending marker is not persisted as business data",()->{JSONObject s=snapshot();yes(DriveJournalRules.apply(s,one(action("ui","worklog",work("w1").put("pending",true)))).length()==0);yes(!s.getJSONArray("worklogs").getJSONObject(0).has("pending"));});
        System.out.println("Passed "+passed+" Drive journal tests using isolated data.");
    }
}
